create or replace function public.assert_admin_header()
returns void
language plpgsql
security definer
set search_path = public
as $admincheck$
declare
  v_headers jsonb;
  v_code text;
begin
  v_headers := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::jsonb;
  v_code := trim(coalesce(v_headers ->> 'x-admin-code', ''));

  if not exists (
    select 1 from public.list_access_codes
    where active = true and is_admin = true and code = v_code
  ) then
    raise exception 'Accès administrateur refusé.' using errcode = '42501';
  end if;
end;
$admincheck$;

revoke execute on function public.assert_admin_header() from anon, authenticated;

create or replace function public.admin_list_pending_suggestions()
returns setof public.gift_suggestions
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.assert_admin_header();

  return query
  select *
  from public.gift_suggestions
  where status = 'pending'
  order by created_at asc;
end;
$$;

grant execute on function public.admin_list_pending_suggestions() to anon;

create or replace function public.admin_set_suggestion_status(
  p_id bigint,
    p_status text
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.assert_admin_header();

  if p_status not in ('approved','rejected') then
    raise exception 'invalid status';
  end if;

  update public.gift_suggestions
  set status = p_status
  where id = p_id
    and status = 'pending';

  return found;
end;
$$;

grant execute on function public.admin_set_suggestion_status(bigint, text) to anon;

