create or replace function public.admin_activity_daily()
returns table (
  day date,
  total bigint,
  visits bigint,
  reservations bigint,
  contributions bigint,
  messages bigint,
  ideas bigint,
  suggestions bigint,
  community bigint,
  fundraisers bigint,
  reactions bigint
)
language plpgsql
security definer
set search_path = ''
as $daily$
begin
  perform public.assert_admin_header();
  return query
  with days as (
    select generate_series(current_date - 6, current_date, interval '1 day')::date as day
  )
  select
    d.day,
    count(a.id) as total,
    count(a.id) filter (where a.entity_type = 'Visite') as visits,
    count(a.id) filter (where a.entity_type = 'Réservation') as reservations,
    count(a.id) filter (where a.entity_type = 'Participation') as contributions,
    count(a.id) filter (where a.entity_type = 'Message') as messages,
    count(a.id) filter (where a.entity_type = 'Idée') as ideas,
    count(a.id) filter (where a.entity_type = 'Suggestion') as suggestions,
    count(a.id) filter (where a.entity_type = 'Communauté') as community,
    count(a.id) filter (where a.entity_type = 'Cagnotte') as fundraisers,
    count(a.id) filter (where a.entity_type = 'Réaction') as reactions
  from days d
  left join public.audit_logs a
    on a.created_at::date = d.day
  group by d.day
  order by d.day;
end;
$daily$;

grant execute on function public.admin_activity_daily() to anon;

