-- =====================================================
-- PROFILS DES INVITÉS / PERSONNES DU SITE
-- =====================================================

create table if not exists public.guest_profiles (
  id bigint generated by default as identity primary key,
  name text not null check (char_length(trim(name)) between 1 and 50),
  relation text not null check (relation in ('Ami(e)','Famille','Camarade de classe','Connaissance','Autre')),
  avatar text,
  bio text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.guest_profiles enable row level security;
revoke all on table public.guest_profiles from anon, authenticated;

create unique index if not exists guest_profiles_name_lower_idx
on public.guest_profiles (lower(trim(name)));

create or replace function public.upsert_guest_profile(
  p_name text,
  p_relation text,
  p_avatar text default null,
  p_bio text default null
)
returns bigint
language plpgsql
security definer
set search_path = public
as $profile$
declare
  profile_id bigint;
begin
  if char_length(trim(coalesce(p_name,''))) < 1
     or char_length(trim(p_name)) > 50
     or p_relation not in ('Ami(e)','Famille','Camarade de classe','Connaissance','Autre')
     or char_length(coalesce(p_avatar,'')) > 4
     or char_length(coalesce(p_bio,'')) > 250
  then
    raise exception 'profil invalide';
  end if;

  insert into public.guest_profiles(name, relation, avatar, bio, updated_at)
  values (
    trim(p_name),
    p_relation,
    nullif(trim(p_avatar),''),
    nullif(trim(p_bio),''),
    now()
  )
  on conflict ((lower(trim(name))))
  do update set
    name = excluded.name,
    relation = excluded.relation,
    avatar = excluded.avatar,
    bio = excluded.bio,
    updated_at = now()
  returning id into profile_id;

  return profile_id;
end;
$profile$;

grant execute on function public.upsert_guest_profile(text,text,text,text) to anon;

create or replace function public.admin_list_guest_profiles()
returns table (
  id bigint,
  name text,
  relation text,
  avatar text,
  bio text,
  created_at timestamptz,
  updated_at timestamptz,
  messages_count bigint,
  ideas_count bigint,
  suggestions_count bigint,
  contributions_count bigint,
  community_count bigint
)
language plpgsql
security definer
set search_path = public
as $people$
begin
  perform public.assert_admin_header();
  return query
  select
    p.id,
    p.name,
    p.relation,
    p.avatar,
    p.bio,
    p.created_at,
    p.updated_at,
    (select count(*) from public.messages m where lower(trim(m.name))=lower(trim(p.name))) as messages_count,
    (select count(*) from public.ideas i where lower(trim(i.name))=lower(trim(p.name))) as ideas_count,
    (select count(*) from public.gift_suggestions s where lower(trim(s.name))=lower(trim(p.name))) as suggestions_count,
    (select count(*) from public.contributions c where lower(trim(c.name))=lower(trim(p.name))) as contributions_count,
    (select count(*) from public.community_posts cp where lower(trim(cp.name))=lower(trim(p.name))) as community_count
  from public.guest_profiles p
  order by p.updated_at desc;
end;
$people$;

grant execute on function public.admin_list_guest_profiles() to anon;


-- ============================================================
-- LISTE D'ANNIVERSAIRE PRIVÉE : catalogue + codes d'accès
-- Les cadeaux ne sont plus stockés dans index.html.
-- Le navigateur ne peut récupérer le catalogue qu'avec un code actif.
-- ============================================================

create table if not exists public.gift_catalog (
  id text primary key,
  sort_order integer not null default 0,
  cat text not null,
  title text not null,
  price text not null,
  description text not null,
  image text,
  official_label text,
  official_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.gift_catalog enable row level security;
revoke all on table public.gift_catalog from anon, authenticated;

alter table public.gift_catalog
add column if not exists archived boolean not null default false;

-- Colonnes ajoutées pour le financement et la gestion des réservations.
-- Ces ALTER sont idempotents : ils réparent aussi une base déjà créée avec l'ancien schéma.
alter table public.gift_catalog
  add column if not exists target_amount numeric not null default 0,
  add column if not exists allow_contributions boolean not null default false,
  add column if not exists allow_reservation boolean not null default true,
  add column if not exists funding_note text;

-- Participations aux cadeaux : données privées, accessibles uniquement via les RPC sécurisées.
-- Cette table était utilisée par les fonctions de financement sans être créée
-- dans les anciennes versions du script.
create table if not exists public.gift_contributions (
  id bigint generated by default as identity primary key,
  gift_id text not null,
  name text not null check (char_length(trim(name)) between 1 and 50),
  amount numeric(10,2) not null check (amount >= 1 and amount <= 5000),
  message text,
  created_at timestamptz not null default now()
);

create index if not exists gift_contributions_gift_id_idx
  on public.gift_contributions (gift_id);

alter table public.gift_contributions enable row level security;
revoke all on table public.gift_contributions from anon, authenticated;

create table if not exists public.list_access_codes (
  id bigint generated by default as identity primary key,
  label text not null check (char_length(trim(label)) between 1 and 80),
  code text not null unique check (char_length(trim(code)) between 8 and 64),
  active boolean not null default true,
  created_at timestamptz not null default now(),
  last_used_at timestamptz
);

create table if not exists public.list_access_authorizations (
  id bigint generated by default as identity primary key,
  access_id bigint not null references public.list_access_codes(id) on delete cascade,
  authorized_at timestamptz not null default now()
);

alter table public.list_access_authorizations enable row level security;
revoke all on table public.list_access_authorizations from anon, authenticated;

alter table public.list_access_codes enable row level security;
revoke all on table public.list_access_codes from anon, authenticated;
alter table public.list_access_codes add column if not exists is_admin boolean not null default false;
alter table public.list_access_codes
  add column if not exists hydra_player_name text;

-- Plusieurs dossiers Hydra peuvent être associés au même accès principal.
-- Chaque dossier possède un jeton privé distinct : partager le code principal
-- ne donne pas accès aux autres dossiers Hydra.
create table if not exists public.hydra_access_assignments (
  id bigint generated by default as identity primary key,
  access_id bigint not null references public.list_access_codes(id) on delete cascade,
  hydra_player_name text not null,
  private_token text not null unique,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  unique(access_id, hydra_player_name)
);

create index if not exists hydra_access_assignments_access_idx
  on public.hydra_access_assignments(access_id);

alter table public.hydra_access_assignments enable row level security;
revoke all on table public.hydra_access_assignments from anon, authenticated;

-- Migration des anciennes attributions uniques vers le système de jetons privés.
insert into public.hydra_access_assignments(access_id,hydra_player_name,private_token,active)
select
  lac.id,
  trim(lac.hydra_player_name),
  'HYDRA-' || upper(substr(md5(lac.code || trim(lac.hydra_player_name) || random()::text || clock_timestamp()::text),1,24)),
  lac.active
from public.list_access_codes lac
where coalesce(trim(lac.hydra_player_name),'') <> ''
  and not exists(
    select 1
    from public.hydra_access_assignments haa
    where haa.access_id=lac.id
      and lower(trim(haa.hydra_player_name))=lower(trim(lac.hydra_player_name))
  )
on conflict (access_id,hydra_player_name) do nothing;




-- ============================================================
-- DEMANDES DE CRÉATION D'ACCÈS
-- Une personne peut demander un accès depuis la page verrouillée.
-- Seul un administrateur peut accepter/refuser la demande et créer le code.
-- ============================================================

create table if not exists public.access_requests (
  id bigint generated by default as identity primary key,
  name text not null check (char_length(trim(name)) between 1 and 50),
  relation text not null check (relation in ('Ami(e)','Famille','Camarade de classe','Connaissance','Autre')),
  avatar text,
  bio text,
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  access_id bigint references public.list_access_codes(id) on delete set null,
  created_at timestamptz not null default now(),
  reviewed_at timestamptz
);

create index if not exists access_requests_status_created_idx
on public.access_requests(status, created_at desc);

create unique index if not exists access_requests_pending_name_idx
on public.access_requests(lower(trim(name)))
where status = 'pending';

alter table public.access_requests enable row level security;
revoke all on table public.access_requests from anon, authenticated;

create or replace function public.submit_access_request(
  p_name text,
  p_relation text,
  p_avatar text default null,
  p_bio text default null
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $accessrequest$
declare
  v_name text := trim(coalesce(p_name,''));
  v_avatar text := trim(coalesce(p_avatar,''));
  v_bio text := trim(coalesce(p_bio,''));
  v_id bigint;
begin
  if char_length(v_name) < 1 or char_length(v_name) > 50
     or p_relation not in ('Ami(e)','Famille','Camarade de classe','Connaissance','Autre')
     or char_length(v_avatar) > 4
     or char_length(v_bio) > 250 then
    raise exception 'Demande invalide.';
  end if;

  if exists(
    select 1
    from public.list_access_codes lac
    where lac.active=true
      and lower(trim(lac.label))=lower(v_name)
  ) then
    raise exception 'Un accès actif existe déjà pour ce nom.';
  end if;

  if exists(
    select 1
    from public.access_requests ar
    where ar.status='pending'
      and lower(trim(ar.name))=lower(v_name)
  ) then
    raise exception 'Une demande est déjà en attente pour ce nom.';
  end if;

  insert into public.access_requests(name,relation,avatar,bio)
  values(v_name,p_relation,nullif(v_avatar,''),nullif(v_bio,''))
  returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'request_id',v_id,
    'status','pending'
  );
end;
$accessrequest$;

grant execute on function public.submit_access_request(text,text,text,text) to anon;

create or replace function public.admin_list_pending_access_requests()
returns table(
  id bigint,
  name text,
  relation text,
  avatar text,
  bio text,
  created_at timestamptz
)
language plpgsql
security definer
set search_path=public
as $accessadminlist$
begin
  perform public.assert_admin_header();
  return query
  select ar.id,ar.name,ar.relation,ar.avatar,ar.bio,ar.created_at
  from public.access_requests ar
  where ar.status='pending'
  order by ar.created_at asc;
end;
$accessadminlist$;

grant execute on function public.admin_list_pending_access_requests() to anon;

create or replace function public.admin_approve_access_request(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $accessapprove$
declare
  v_req public.access_requests%rowtype;
  v_access_id bigint;
  v_code text;
begin
  perform public.assert_admin_header();

  select * into v_req
  from public.access_requests
  where id=p_id and status='pending'
  for update;

  if not found then
    raise exception 'Demande introuvable ou déjà traitée.';
  end if;

  loop
    v_code := 'ETHAN-' || upper(substr(md5(random()::text || clock_timestamp()::text || p_id::text),1,20));
    exit when not exists(select 1 from public.list_access_codes where code=v_code);
  end loop;

  insert into public.list_access_codes(label,code,active,is_admin)
  values(v_req.name,v_code,true,false)
  returning id into v_access_id;

  insert into public.guest_profiles(name,relation,avatar,bio,updated_at)
  values(v_req.name,v_req.relation,v_req.avatar,v_req.bio,now())
  on conflict ((lower(trim(name))))
  do update set
    name=excluded.name,
    relation=excluded.relation,
    avatar=excluded.avatar,
    bio=excluded.bio,
    updated_at=now();

  update public.access_requests
  set status='approved',
      access_id=v_access_id,
      reviewed_at=now()
  where id=p_id;

  return jsonb_build_object(
    'ok',true,
    'request_id',p_id,
    'access_id',v_access_id,
    'label',v_req.name,
    'code',v_code
  );
end;
$accessapprove$;

grant execute on function public.admin_approve_access_request(bigint) to anon;

create or replace function public.admin_reject_access_request(p_id bigint)
returns boolean
language plpgsql
security definer
set search_path=public
as $accessreject$
begin
  perform public.assert_admin_header();
  update public.access_requests
  set status='rejected',
      reviewed_at=now()
  where id=p_id and status='pending';
  return found;
end;
$accessreject$;

grant execute on function public.admin_reject_access_request(bigint) to anon;

-- Protection anti-brute-force de l'authentification des codes d'accès.
-- Le compteur est basé sur l'IP vue par la passerelle Supabase et se réinitialise
-- après une authentification réussie. Aucun code d'accès n'est stocké dans cette table.
create table if not exists public.list_access_rate_limits (
  client_ip text primary key,
  failed_attempts integer not null default 0,
  last_failed_at timestamptz,
  blocked_until timestamptz
);

alter table public.list_access_rate_limits enable row level security;
revoke all on table public.list_access_rate_limits from anon, authenticated;

-- ============================================================
-- TÉLÉMÉTRIE DE L'EXTENSION — CONSENTEMENT EXPLICITE
-- Les données sont envoyées uniquement après acceptation dans
-- l'extension. Aucun mot de passe ou code d'accès n'est collecté.
-- ============================================================

create table if not exists public.extension_telemetry_events (
  id bigint generated by default as identity primary key,
  installation_id uuid not null,
  session_id uuid not null,
  event_type text not null check (
    event_type in (
      'consent_granted',
      'page_view',
      'click',
      'resize',
      'network_online',
      'network_offline',
      'visibility_hidden'
    )
  ),
  page_path text not null check (
    char_length(trim(page_path)) between 1 and 220
    and position('?' in page_path) = 0
    and position('#' in page_path) = 0
  ),
  event_label text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists extension_telemetry_events_created_at_idx
  on public.extension_telemetry_events (created_at desc);

create index if not exists extension_telemetry_events_installation_idx
  on public.extension_telemetry_events (installation_id, created_at desc);

create index if not exists extension_telemetry_events_session_idx
  on public.extension_telemetry_events (session_id, created_at desc);

alter table public.extension_telemetry_events enable row level security;
revoke all on table public.extension_telemetry_events from anon, authenticated;

create or replace function public.extension_log_event(
  p_installation_id uuid,
  p_session_id uuid,
  p_event_type text,
  p_page_path text,
  p_event_label text default null,
  p_metadata jsonb default '{}'::jsonb
)
returns bigint
language plpgsql
security definer
set search_path = public
as $telemetry$
declare
  v_id bigint;
  v_type text;
  v_page text;
  v_label text;
  v_meta jsonb;
begin
  v_type := lower(trim(coalesce(p_event_type, '')));
  v_page := trim(coalesce(p_page_path, ''));
  v_label := nullif(left(trim(coalesce(p_event_label, '')), 160), '');

  if p_installation_id is null or p_session_id is null then
    raise exception 'Identifiant de télémétrie invalide.';
  end if;

  if v_type not in (
    'consent_granted',
    'page_view',
    'click',
    'resize',
    'network_online',
    'network_offline',
    'visibility_hidden'
  ) then
    raise exception 'Type d''événement invalide.';
  end if;

  if char_length(v_page) < 1
     or char_length(v_page) > 220
     or position('?' in v_page) > 0
     or position('#' in v_page) > 0
     or left(v_page, 1) <> '/'
  then
    raise exception 'Page invalide.';
  end if;

  p_metadata := coalesce(p_metadata, '{}'::jsonb);
  if jsonb_typeof(p_metadata) <> 'object' then
    p_metadata := '{}'::jsonb;
  end if;

  -- Liste blanche des informations techniques réellement conservées.
  v_meta := jsonb_strip_nulls(jsonb_build_object(
    'title', left(coalesce(p_metadata->>'title',''), 160),
    'language', left(coalesce(p_metadata->>'language',''), 20),
    'timezone', left(coalesce(p_metadata->>'timezone',''), 80),
    'online', left(coalesce(p_metadata->>'online',''), 10),
    'colorScheme', left(coalesce(p_metadata->>'colorScheme',''), 10),
    'touchPoints', left(coalesce(p_metadata->>'touchPoints',''), 10),
    'connectionType', left(coalesce(p_metadata->>'connectionType',''), 20),
    'viewportWidth', left(coalesce(p_metadata->>'viewportWidth',''), 10),
    'viewportHeight', left(coalesce(p_metadata->>'viewportHeight',''), 10),
    'screenWidth', left(coalesce(p_metadata->>'screenWidth',''), 10),
    'screenHeight', left(coalesce(p_metadata->>'screenHeight',''), 10),
    'extensionVersion', left(coalesce(p_metadata->>'extensionVersion',''), 20)
  ));

  insert into public.extension_telemetry_events(
    installation_id,
    session_id,
    event_type,
    page_path,
    event_label,
    metadata
  )
  values(
    p_installation_id,
    p_session_id,
    v_type,
    v_page,
    v_label,
    v_meta
  )
  returning id into v_id;

  return v_id;
end;
$telemetry$;

grant execute on function public.extension_log_event(uuid,uuid,text,text,text,jsonb) to anon;

create or replace function public.admin_list_extension_events(
  p_limit integer default 250
)
returns table(
  event_id bigint,
  installation_id uuid,
  session_id uuid,
  event_type text,
