  $hydra_full${"enabled":true,"title":"Dossier Hydra — Murder Party","date":"23 décembre 2026","location":"Chez Yanick et Cécile","key_moment":"21h10 précises","invitation":{"title":"PROTOCOLE HYDRA – ENQUÊTE FAMILIALE","intro":"Le temps d'une journée entière, devenez agent secret.","body":"L'île flottante du milliardaire visionnaire a sombré dans le chaos. Une IA rebelle, deux poisons expérimentaux, un livre ancien volé et un clone en liberté. Saurez-vous démêler le vrai du faux avant que la dictature numérique ne prenne le contrôle ?","mission_location":"Chez Yanick et Cécile","date":"23 décembre","time":"Toute la journée (à partir de l'heure convenue).","key_moment":"21h10 précises : une surprise viendra marquer l'instant exact de la naissance d'Ethan.","outfit":"Agent secret, enquêteur ou chic sobre (noir, rouge, lunettes fumées, accessoire stylé). Un simple badge ou une cravate suffit.","preparation":"Avant le 23 décembre, vous recevrez par message votre dossier secret contenant trois documents : votre fiche personnage (identité secrète, rôle et objectif personnel), un document spécial (un indice unique que vous seul détenez) et un fragment IA (un morceau de l'enregistrement du meurtre). Lisez ces documents attentivement avant la journée. Imprégnez-vous de votre personnage, de ses secrets et de ses intentions.","phases":["Découverte du crime et présentation des rôles","Enquête libre (interrogatoires, exploration des zones, recherche d'indices)","Révélations (rassemblement des fragments IA et décryptage du livre ancien)","Accusation finale et surprise de 21h10"],"note":"Le milliardaire est mort. L'IA Hydra a effacé les preuves… ou pas. Snow, le chat du Chef Hydra, a repéré un suspect. Une page du livre ancien a disparu. Et si l'un d'entre vous n'était pas tout à fait humain ? Préparez-vous à douter de tout le monde."},"players":[{"name":"Ethan","role":"Chef Hydra","function":"Coordinateur central, cerveau de l’enquête.","description":"Tu supervises l'organisation et les déplacements des joueurs. Tu es le chef de l'enquête.","knowledge":"Hydra est une structure numérique secrète. Un corps a été retrouvé sur l'île flottante. L'IA Hydra a crypté l'enregistrement du meurtre en 12 fragments.","objective":"Organiser l'enquête, distribuer les documents, identifier le coupable.","special_text":"Ordre du Chef Hydra — « Distribuer les fragments IA. Ne rien dire sur leur origine. Chef. »","special":"Ordre du Chef Hydra — « Distribuer les fragments IA. Ne rien dire sur leur origine. Chef. »","fragment":"Fragment IA 1 : « Le protocole Hydra-Core a été déclenché avant l'incident. »","companion":"Snow, ton chat blanc. Il te suit partout. Il détecte les menteurs et les traces de poison.","rule":"","fictional_hook":"","tenue_parfaite":"Blazer noir, chemise blanche, cravate bordeaux, pantalon noir droit, chaussures noires en cuir, montre sombre et dossier Hydra sous le bras."},{"name":"Serge","role":"Patient Hydra","function":"Patient chronique, témoin clé.","description":"Tu es souvent à l'infirmerie et tu as vu des choses étranges. Tu es persuadé qu'Hydra t'a rendu malade.","knowledge":"Tu as été examiné récemment. Les bijoux de la victime faisaient « bip bip » près de toi.","objective":"Comprendre ce qui t'arrive et ce que tu as vu à l'infirmerie.","special_text":"Dossier Médical Hydra — « Traces Alpha : faibles mais présentes. Symptômes compatibles avec une exposition récente. »","special":"Dossier Médical Hydra — « Traces Alpha : faibles mais présentes. Symptômes compatibles avec une exposition récente. »","fragment":"Fragment IA 2 : « Traces Alpha détectées sur un sujet vivant. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Blouse blanche de médecin, chemise bleu pâle, pantalon gris anthracite, baskets blanches sobres et badge Hydra accroché à la poche."},{"name":"Silvie","role":"Protectrice du Livre Ancien","function":"Gardienne du secret, mémoire du livre.","description":"Tu protèges un livre très ancien contenant un secret d'État. Tu ne lis pas bien mais tu vois tout.","knowledge":"Une page du livre a disparu. Tu sais qui a touché le livre, qui a volé la page, qui a caché les bijoux dedans.","objective":"Retrouver la page manquante.","special_text":"Extrait du Livre Ancien — « Le sang des deux lignées n'est qu'un seul fleuve. La page manquante révèle l'héritier véritable. »","special":"Extrait du Livre Ancien — « Le sang des deux lignées n'est qu'un seul fleuve. La page manquante révèle l'héritier véritable. »","fragment":"Fragment IA 3 : « La page manquante contient l'identité réelle de la victime. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Manteau long vert forêt, blouse ivoire à col fermé, pantalon noir droit, bottines marron foncé, sacoche en cuir et petit pendentif-livre."},{"name":"Fabrice","role":"Archiviste Numérique Hydra","function":"Gestion des données et archives.","description":"Tu analyses les fichiers, les métadonnées, les archives Hydra.","knowledge":"Certains fichiers semblent altérés. L'IA a effacé des données.","objective":"Comprendre les anomalies dans les données.","special_text":"Dossier OSINT — « Altération détectée. Source : Hydra-Core. Horodatage incohérent. »","special":"Dossier OSINT — « Altération détectée. Source : Hydra-Core. Horodatage incohérent. »","fragment":"Fragment IA 4 : « Altération du fichier vidéo. Horodatage incohérent. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Surchemise gris charbon, t-shirt noir uni, jean noir, baskets noires, sacoche d’ordinateur et badge d’archive numérique."},{"name":"Jean-Louis Pineau","role":"Pilote de l’Île Flottante","function":"Navigation et contrôle des déplacements.","description":"Tu conduis l'île flottante. Tu sais qui est monté, descendu, ou s'est caché dans les zones interdites.","knowledge":"Une déviation imprévue a eu lieu.","objective":"Comprendre les mouvements suspects de l'île.","special_text":"Journal de Navigation — « 21h52 : déviation non programmée. Trajectoire modifiée sans autorisation. »","special":"Journal de Navigation — « 21h52 : déviation non programmée. Trajectoire modifiée sans autorisation. »","fragment":"Fragment IA 5 : « Déviation de trajectoire enregistrée à 21h52. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Blouson pilote bleu marine, chemise blanche, pantalon chino beige, mocassins marron foncé et montre de navigation."},{"name":"Jean-Louis Meal","role":"Espion Hydra","function":"Infiltration, surveillance.","description":"Tu es un agent infiltré. Tu as deux identités. Tu mens. Tu caches quelque chose.","knowledge":"Tu as reçu un ordre secret : surveiller un joueur.","objective":"Remplir ta mission sans te faire repérer.","special_text":"Ordre Secret Hydra — « Surveiller le sujet Y. Risque Omega élevé. Ne pas révéler la mission. »","special":"Ordre Secret Hydra — « Surveiller le sujet Y. Risque Omega élevé. Ne pas révéler la mission. »","fragment":"Fragment IA 6 : « Un individu a été observé deux fois au même endroit. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Col roulé noir, surchemise gris anthracite, pantalon noir, bottines noires et petite oreillette discrète."},{"name":"Cécile","role":"Sentinelle Hydra","function":"Observation, surveillance.","description":"Tu observes les comportements et les déplacements. Tu as des yeux partout.","knowledge":"Tu as vu une silhouette étrange.","objective":"Identifier les comportements suspects.","special_text":"Rapport d'Observation — « 22h14 : silhouette identique à la victime observée. Déplacement non expliqué. »","special":"Rapport d'Observation — « 22h14 : silhouette identique à la victime observée. Déplacement non expliqué. »","fragment":"Fragment IA 7 : « Silhouette identique détectée à 22h14. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Veste de terrain vert olive, t-shirt noir, pantalon cargo noir, chaussures de randonnée sombres et lampe compacte à la ceinture."},{"name":"Annie","role":"Matriarche Hydra","function":"Mémoire familiale depuis 40 ans.","description":"Tu connais l'histoire des familles liées à Hydra.","knowledge":"Un ancien conflit familial existe. Les deux familles ennemies sont en réalité la même.","objective":"Comprendre le lien entre les familles et Hydra.","special_text":"Mémoire Familiale — « En 1824, la lignée fut divisée pour protéger un secret d'État. Ce secret n'a jamais été révélé. »","special":"Mémoire Familiale — « En 1824, la lignée fut divisée pour protéger un secret d'État. Ce secret n'a jamais été révélé. »","fragment":"Fragment IA 8 : « Les deux lignées ne forment qu'une seule famille. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Gilet bordeaux, blouse crème, pantalon ou jupe midi bleu nuit, bottines noires, broche ancienne et petit sac structuré."},{"name":"Max","role":"Agent OSINT","function":"Analyse numérique, métadonnées.","description":"Tu analyses les métadonnées et les fichiers.","knowledge":"Un message crypté a été trouvé.","objective":"Décrypter les informations.","special_text":"Message Crypté — Coordonnées : 47.3 / 12.9 « Zone interdite. Décryptage nécessaire. »","special":"Message Crypté — Coordonnées : 47.3 / 12.9 « Zone interdite. Décryptage nécessaire. »","fragment":"Fragment IA 9 : « Message crypté : “Il n'est pas celui que vous croyez.” »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Surchemise bleu marine, t-shirt gris clair, jean brut sombre, baskets blanches et grises, lunettes sobres et sacoche technique."},{"name":"Yoan","role":"Saboteur Repenti","function":"Manipulation technique.","description":"Tu as saboté quelque chose sans savoir que ça tuerait la victime.","knowledge":"Un passage technique est endommagé.","objective":"Comprendre ton rôle dans les sabotages.","special_text":"Schéma de Sabotage — « Sabotage mineur effectué. Impact imprévu sur la zone technique. »","special":"Schéma de Sabotage — « Sabotage mineur effectué. Impact imprévu sur la zone technique. »","fragment":"Fragment IA 10 : « Sabotage mineur enregistré. Impact imprévu. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Veste de travail brun foncé, t-shirt rouille, pantalon cargo anthracite, chaussures de sécurité noires et petite sacoche à outils."},{"name":"Marie-Françoise","role":"Gardienne des Bijoux Hydra","function":"Gestion des bijoux traceurs.","description":"Tu surveilles les bijoux Hydra équipés de traceurs et micro-caméras.","knowledge":"Un bijou a disparu.","objective":"Retrouver le bijou manquant.","special_text":"Inventaire des Bijoux Hydra — Bijou 3 : « Signal détecté près de Serge. Objet manquant. »","special":"Inventaire des Bijoux Hydra — Bijou 3 : « Signal détecté près de Serge. Objet manquant. »","fragment":"Fragment IA 11 : « Bijou 3 : signal détecté près d'un sujet instable. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Blazer bleu nuit, blouse ivoire, pantalon noir droit, mocassins noirs, broche dorée discrète et petite boîte à bijoux."},{"name":"Claudie","role":"Psychologue Hydra","function":"Profilage mental, analyse comportementale.","description":"Tu observes les comportements et les réactions. Tu as accès aux dossiers mentaux Hydra.","knowledge":"Un joueur semble instable.","objective":"Comprendre les comportements altérés.","special_text":"Profil Mental Hydra — « Sujet X : comportement altéré après exposition Omega. Instabilité observée. »","special":"Profil Mental Hydra — « Sujet X : comportement altéré après exposition Omega. Instabilité observée. »","fragment":"Fragment IA 12 : « Comportement altéré après exposition Omega. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Veste longue beige, blouse vert sauge, pantalon anthracite, bottines marron clair, carnet et stylo dans une petite sacoche."},{"name":"Andrea","role":"Protectrice des Animaux Hydra","function":"Gestion et interprétation de Milo.","description":"Tu interprètes les réactions du chien Milo.","knowledge":"Milo a réagi dans une zone précise.","objective":"Suivre Milo et comprendre ses réactions.","special_text":"Rapport Milo — « Zone 3 : réaction forte du chien. Traces Omega détectées. »","special":"Rapport Milo — « Zone 3 : réaction forte du chien. Traces Omega détectées. »","fragment":"Fragment IA 13 : « Zone 3 : traces Omega détectées par unité biologique. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Veste de terrain vert olive, t-shirt écru, pantalon kaki, chaussures de randonnée beige et vert foncé, sac bandoulière et médaille Hydra."},{"name":"Mario","role":"Gardien de Milo","function":"Suivi du chien détecteur.","description":"Tu accompagnes Milo et récupères les indices qu'il trouve.","knowledge":"Milo a trouvé un objet.","objective":"Suivre Milo et rapporter les indices.","special_text":"Note de Terrain — « 20h31 : Milo a trouvé un bijou Hydra. Objet récupéré. »","special":"Note de Terrain — « 20h31 : Milo a trouvé un bijou Hydra. Objet récupéré. »","fragment":"Fragment IA 14 : « Objet Hydra trouvé à 20h31. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Sweat à capuche vert forêt sous une veste sans manches bleu marine, jean noir, chaussures de randonnée et sifflet de dressage au cou."},{"name":"Tony","role":"Mini-Analyste OSINT","function":"Analyse visuelle, QR codes, symboles.","description":"Tu repères les symboles et les QR codes. Tu es super motivé !","knowledge":"Un symbole Hydra est apparu.","objective":"Identifier les logos Hydra.","special_text":"Symbole Hydra — Mot-clé : « Omega ». « Ce symbole apparaît sur les objets liés au poison. »","special":"Symbole Hydra — Mot-clé : « Omega ». « Ce symbole apparaît sur les objets liés au poison. »","fragment":"Fragment IA 15 : « Symbole Hydra associé au protocole Omega. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Surchemise bleu moyen, t-shirt blanc, pantalon cargo noir, baskets gris clair, petite sacoche tech et badge OSINT."},{"name":"Lino","role":"Gardien des Objets Hydra","function":"Protection des reliques.","description":"Tu protèges un objet important.","knowledge":"L'objet doit rester en sécurité.","objective":"Ne jamais perdre l'objet.","special_text":"Objet Sacré Hydra — « Ne le laisse jamais tomber. Cet objet doit rester en sécurité. »","special":"Objet Sacré Hydra — « Ne le laisse jamais tomber. Cet objet doit rester en sécurité. »","fragment":"Fragment IA 16 : « L'objet sacré est lié à l'identité de la victime. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Surchemise marron chocolat, t-shirt gris charbon, pantalon noir, bottes marron foncé, sacoche en toile et trousse à objets Hydra."},{"name":"Emy","role":"Secrétaire du Chef Hydra","function":"Assistance opérationnelle.","description":"Tu aides Ethan dans l'organisation. Tu distribues les fiches.","knowledge":"Tu dois distribuer certains documents.","objective":"Suivre les instructions du Chef.","special_text":"Ordre du Chef Hydra — « Distribuer les fragments IA. Ne rien dire sur leur origine. Chef. »","special":"Ordre du Chef Hydra — « Distribuer les fragments IA. Ne rien dire sur leur origine. Chef. »","fragment":"Fragment IA 17 : « Fragment IA distribué par ordre du Chef. »","companion":"","rule":"Tu dois dire « Chef ! » à la fin de chaque phrase pendant toute la journée. C'est ton code secret.","fictional_hook":"","tenue_parfaite":"Blazer prune, chemise blanche, pantalon noir droit, mocassins noirs, petite montre et porte-documents fin."},{"name":"Milo","role":"Chien Détecteur Hydra","function":"Détection biologique des poisons.","description":"Tu renifles les objets et les zones.","knowledge":"Tu réagis à certains endroits.","objective":"Trouver des indices.","special_text":"Carte des Zones Reniflées — Zone 1 : neutre. Zone 2 : traces Alpha. Zone 3 : traces Omega.","special":"Carte des Zones Reniflées — Zone 1 : neutre. Zone 2 : traces Alpha. Zone 3 : traces Omega.","fragment":"Fragment IA 18 : « Zone 2 : traces Alpha détectées. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Harnais bleu nuit avec écusson Hydra, bandana rouge sombre, médaille d’identification et petite cape légère imperméable pour les déplacements."},{"name":"Emilie","role":"Comptable Hydra","function":"Gestion des comptes, flux financiers, paradis fiscaux.","description":"Tu tiens les comptes d'Hydra. Tu vois passer les virements, les comptes offshore, les sociétés écrans. Tu es discrète, précise, et tu remarques tout ce qui ne tourne pas rond.","knowledge":"Tu as repéré un virement suspect de 2,3 millions vers un compte offshore, juste avant la mort du milliardaire. L'horodatage est incohérent. Tu penses qu'une partie de l'argent a servi à financer un sabotage.","objective":"Découvrir qui a détourné l'argent et ce qu'il a payé. Retrouver la trace du virement avant que quelqu'un ne l'efface.","special_text":"Relevé Bancaire Hydra — « Virement de 2,3 millions vers compte offshore. Date incohérente. Bénéficiaire inconnu. »","special":"Relevé Bancaire Hydra — « Virement de 2,3 millions vers compte offshore. Date incohérente. Bénéficiaire inconnu. »","fragment":"Fragment IA 19 : « Un transfert a été effectué avant l'incident. »","companion":"","rule":"","fictional_hook":"","tenue_parfaite":"Blazer gris ardoise, chemise blanche, pantalon noir droit, mocassins noirs, montre sobre et porte-documents avec relevés Hydra."}],"zones":[{"name":"ZONE 1 – Zone Neutre","description":"Espace sans activité particulière. Aucun sabotage signalé. Aucune anomalie visible.","knowledge":"Cette zone ne présente aucun danger connu.","milo_detected":"Aucune réaction. Aucune trace de poison.","finds":"Objet neutre, Fragment IA mineur, Indice mineur."},{"name":"ZONE 2 – Zone Alpha","description":"Espace où des analyses ont été menées. Des traces chimiques ont été signalées. Un passage semble avoir été utilisé récemment.","knowledge":"Le poison Alpha provoque une obéissance totale pendant quelques minutes.","milo_detected":"Réaction modérée. Traces Alpha identifiées.","finds":"Fioles Alpha, Dossier médical, Fragment IA, Objet déplacé."},{"name":"ZONE 3 – Zone Omega","description":"Espace en désordre. Objets cassés. Griffures visibles sur les parois. Comportements violents signalés.","knowledge":"Le poison Omega provoque des hallucinations et des comportements instables.","milo_detected":"Réaction forte. Traces Omega identifiées.","finds":"Objets brisés, Rapport d'analyse Omega, Fragment IA, Indice majeur."},{"name":"ZONE 4 – Zone de Sabotage","description":"Passage technique endommagé. Impact imprévu. Accès restreint.","knowledge":"Un sabotage mineur a été enregistré.","milo_detected":"Réaction faible. Aucune trace de poison. Présence d'un objet technique.","finds":"Schéma de sabotage, Objet cassé, Fragment IA."},{"name":"ZONE 5 – Coffre des Bijoux Hydra","description":"Petit espace contenant un coffre. Un bijou manque. Un signal a été détecté.","knowledge":"Les bijoux Hydra sont équipés de traceurs.","milo_detected":"Réaction légère. Signal faible provenant d'un objet.","finds":"Inventaire des bijoux, Emplacement vide, Fragment IA, Objet espion."},{"name":"ZONE 6 – Zone Biologique","description":"Espace où Milo réagit souvent. Objets organiques présents. Traces biologiques au sol.","knowledge":"Milo détecte les poisons Alpha et Omega.","milo_detected":"Réaction variable selon les objets. Traces faibles d'Alpha ou Omega selon le moment.","finds":"Carte des zones reniflées, Objet trouvé par Milo, Fragment IA."},{"name":"ZONE 7 – Salle du Livre Ancien","description":"Salle protégée contenant le livre ancien. Une page manque. Symbole Hydra visible.","knowledge":"La page volée est essentielle.","milo_detected":"Aucune réaction. Aucun poison.","finds":"Livre ancien, Emplacement vide, Symbole Hydra, Fragment IA."},{"name":"ZONE 8 – Salle de Contrôle IA","description":"Salle remplie d'écrans et de serveurs. Certains logs ont été effacés.","knowledge":"L'IA Hydra a enregistré l'incident en 12 fragments.","milo_detected":"Aucune réaction. Aucun poison.","finds":"Logs effacés, Message crypté, Fragment IA."}],"objects":[{"id":1,"name":"Objet 1 – Symbole Hydra","description":"Médaillon métallique gravé du symbole Hydra. Émet une faible lumière rouge en présence d'Omega. Sert à identifier les zones contaminées."},{"id":2,"name":"Objet 2 – Fioles Alpha","description":"Petites fioles transparentes contenant un liquide vert. Permettent de tester la présence du poison Alpha. Une fiole vide a été trouvée dans le laboratoire Alpha."},{"id":3,"name":"Objet 3 – Fioles Omega","description":"Fioles rouges opaques, légèrement chaudes au toucher. Contiennent le poison Omega. Une fiole brisée a été retrouvée dans la zone de sabotage."},{"id":4,"name":"Objet 4 – Bijou Hydra","description":"Collier doré avec un petit cristal lumineux. Sert de traceur pour les membres Hydra. Le bijou manquant est lié à la victime."},{"id":5,"name":"Objet 5 – Carte Hydra","description":"Carte plastifiée avec le logo Hydra et un code QR. Donne accès à la salle de contrôle IA. Le code QR mène à un message crypté."},{"id":6,"name":"Objet 6 – Livre Ancien","description":"Livre relié en cuir, très abîmé. Contient des fragments de l'histoire Hydra. Une page manque, elle révèle l'identité du clone."},{"id":7,"name":"Objet 7 – Fragment IA","description":"Petit module électronique avec une lumière bleue. Contient un message enregistré par l'IA Hydra. Chaque fragment complète le message final."},{"id":8,"name":"Objet 8 – Dossier Médical","description":"Dossier papier avec des analyses sanguines. Prouve l'exposition au poison Alpha. Le nom de Serge y apparaît."},{"id":9,"name":"Objet 9 – Schéma de Sabotage","description":"Plan technique annoté à la main. Montre comment le sabotage a été effectué. Le schéma correspond à la zone 4."},{"id":10,"name":"Objet 10 – Ordre Secret Hydra","description":"Feuille codée avec le sceau Hydra. Contient une mission confidentielle. Jean-Louis Meal est mentionné."},{"id":11,"name":"Objet 11 – Inventaire des Bijoux","description":"Liste manuscrite des bijoux Hydra. Permet de vérifier les objets manquants. Le bijou 3 est noté « signal détecté »."},{"id":12,"name":"Objet 12 – Symbole Omega","description":"Insigne rouge gravé sur une plaque métallique. Marque les zones contaminées. Visible dans le laboratoire Omega."},{"id":13,"name":"Objet 13 – Objet Sacré Hydra","description":"Petite sphère noire, lourde, avec un symbole gravé. Reliée à l'identité de la victime. Lino doit la protéger."},{"id":14,"name":"Objet 14 – Note de Terrain","description":"Feuille froissée avec des observations. Sert à suivre les déplacements. Mentionne un objet trouvé à 20h31."},{"id":15,"name":"Objet 15 – Carte des Zones","description":"Plan simplifié de l'île Hydra. Indique les zones Alpha et Omega. Correspond au plan isométrique."},{"id":16,"name":"Objet 16 – Message Crypté","description":"Feuille avec un texte illisible sans décryptage. Contient une phrase clé : « Il n'est pas celui que vous croyez. » Trouvé dans les archives numériques."},{"id":17,"name":"Objet 17 – Profil Mental Hydra","description":"Dossier psychologique d'un sujet instable. Sert à identifier les comportements altérés. Claudie le possède."},{"id":18,"name":"Objet 18 – Ordre du Chef","description":"Feuille signée « Chef Hydra ». Donne les instructions à Emy. « Distribuer les fragments IA. »"}],"enigmas":[{"id":1,"question":"Je crée des mondes que je ne verrai jamais. Qui suis-je ?","answer":"Le Milliardaire Mort","npc":"Le Milliardaire Mort"},{"id":2,"question":"Je mens mieux que vous ne dites la vérité. Qui suis-je ?","answer":"L'IA Hydra Centrale","npc":"L'IA Hydra Centrale"},{"id":3,"question":"Je suis né pour régner sur quelque chose qui n'existe pas encore. Qui suis-je ?","answer":"Le Dictateur Fils","npc":"Le Dictateur Fils"},{"id":4,"question":"Je décide sans être maître, j'obéis sans être esclave. Qui suis-je ?","answer":"L'IA Hydra Centrale / Le Président Corrompu","npc":"L'IA Hydra Centrale / Le Président Corrompu"},{"id":5,"question":"Je protège en effaçant ce qui pourrait me condamner. Qui suis-je ?","answer":"Le Ministre de la Sécurité","npc":"Le Ministre de la Sécurité"},{"id":6,"question":"Je transforme la vérité en mensonge sans jamais écrire un mot. Qui suis-je ?","answer":"Le Ministre de la Justice","npc":"Le Ministre de la Justice"},{"id":7,"question":"Je crée des règles que personne ne doit connaître. Qui suis-je ?","answer":"Le Sénateur Hydra","npc":"Le Sénateur Hydra"},{"id":8,"question":"Je commande les corps sans jamais les toucher. Qui suis-je ?","answer":"Le Scientifique Alpha","npc":"Le Scientifique Alpha"},{"id":9,"question":"Je fais perdre la raison sans jamais parler. Qui suis-je ?","answer":"Le Scientifique Omega","npc":"Le Scientifique Omega"},{"id":10,"question":"Je dirige ceux qui croient en ce qu'ils ne comprennent pas. Qui suis-je ?","answer":"Le Chef de la Secte Hydra","npc":"Le Chef de la Secte Hydra"},{"id":11,"question":"Je garde un secret que même les dieux ont oublié. Qui suis-je ?","answer":"Le Grand Prêtre Hydra","npc":"Le Grand Prêtre Hydra"},{"id":12,"question":"Je suis invisible, mais je vaux plus que tout ce que vous voyez. Qui suis-je ?","answer":"Le Maître des Paradis Fiscaux","npc":"Le Maître des Paradis Fiscaux"},{"id":13,"question":"Je dis la vérité en chantant le mensonge. Qui suis-je ?","answer":"Le Chanteur du Chantage","npc":"Le Chanteur du Chantage"},{"id":14,"question":"Je construis des accidents avec des plans parfaits. Qui suis-je ?","answer":"L'Architecte du Coup Monté","npc":"L'Architecte du Coup Monté"},{"id":15,"question":"Je suis partout, mais personne ne sait où je suis. Qui suis-je ?","answer":"L'Agent CIA Hydra","npc":"L'Agent CIA Hydra"},{"id":16,"question":"Je vole ce qui ne peut être volé. Qui suis-je ?","answer":"L'Agent MI6 Hydra","npc":"L'Agent MI6 Hydra"},{"id":17,"question":"Je protège en détruisant ce que je devrais défendre. Qui suis-je ?","answer":"L'Agent DGSE Hydra","npc":"L'Agent DGSE Hydra"},{"id":18,"question":"Je sais qui a créé ce qui tue sans bruit. Qui suis-je ?","answer":"L'Agent Mossad Hydra","npc":"L'Agent Mossad Hydra"},{"id":19,"question":"Je suis toi, mais je ne suis pas toi. Qui suis-je ?","answer":"Le Clone Hydra","npc":"Le Clone Hydra"},{"id":20,"question":"Je laisse des traces que personne ne peut suivre. Qui suis-je ?","answer":"Le Hacker Fantôme","npc":"Le Hacker Fantôme"},{"id":21,"question":"Je vois ce que les autres ne remarquent jamais. Qui suis-je ?","answer":"L'Agent GIGN Hydra","npc":"L'Agent GIGN Hydra"},{"id":22,"question":"Je suis passé, présent et futur à la fois. Qui suis-je ?","answer":"L'Agent KGB Hydra","npc":"L'Agent KGB Hydra"},{"id":23,"question":"Je surveille ceux qui surveillent. Qui suis-je ?","answer":"L'Agent FSB Hydra","npc":"L'Agent FSB Hydra"},{"id":24,"question":"Je lis ce que vous n'avez jamais écrit. Qui suis-je ?","answer":"L'Agent NSA Hydra","npc":"L'Agent NSA Hydra"},{"id":25,"question":"Je poursuis ce qui n'a pas de frontières. Qui suis-je ?","answer":"L'Agent Interpol Hydra","npc":"L'Agent Interpol Hydra"},{"id":26,"question":"Je garde ce qui ne doit jamais être ouvert. Qui suis-je ?","answer":"L'Agent Secret Suisse","npc":"L'Agent Secret Suisse"},{"id":27,"question":"Je vois les tests que personne ne doit voir. Qui suis-je ?","answer":"L'Agent Secret Canadien","npc":"L'Agent Secret Canadien"},{"id":28,"question":"J'essaie d'éteindre ce qui n'a pas de bouton. Qui suis-je ?","answer":"L'Agent Secret Japonais","npc":"L'Agent Secret Japonais"},{"id":29,"question":"Je trouve ce qui n'existe pas encore. Qui suis-je ?","answer":"L'Agent Secret Allemand","npc":"L'Agent Secret Allemand"},{"id":30,"question":"Je connais les rituels que personne ne comprend. Qui suis-je ?","answer":"L'Agent Secret Italien","npc":"L'Agent Secret Italien"},{"id":31,"question":"Je suis la trace d'un sabotage oublié. Qui suis-je ?","answer":"L'Agent Secret Espagnol","npc":"L'Agent Secret Espagnol"},{"id":32,"question":"Je vois la vie dans ce qui tue. Qui suis-je ?","answer":"L'Agent Secret Australien","npc":"L'Agent Secret Australien"},{"id":33,"question":"Je suis un réseau sans câbles. Qui suis-je ?","answer":"L'Agent Secret Brésilien","npc":"L'Agent Secret Brésilien"},{"id":34,"question":"Je vois un homme qui n'est pas un homme. Qui suis-je ?","answer":"L'Agent Secret Sud-Africain","npc":"L'Agent Secret Sud-Africain"},{"id":35,"question":"Je manipule ce que vous ressentez. Qui suis-je ?","answer":"L'Agent Secret Coréen","npc":"L'Agent Secret Coréen"},{"id":36,"question":"Je cherche ce que tout le monde cache. Qui suis-je ?","answer":"L'Enquêteur Principal Hydra","npc":"L'Enquêteur Principal Hydra"},{"id":37,"question":"Je suis le fil qui relie les comptes invisibles. Qui suis-je ?","answer":"L'Enquêtrice Internationale","npc":"L'Enquêtrice Internationale"},{"id":38,"question":"Je vois les copies dans l'ombre. Qui suis-je ?","answer":"L'Agent GIPN Hydra","npc":"L'Agent GIPN Hydra"},{"id":39,"question":"Je neutralise ce qui n'a pas de corps. Qui suis-je ?","answer":"L'Agent RAID Hydra","npc":"L'Agent RAID Hydra"},{"id":40,"question":"Je lis les messages que personne n'a envoyés. Qui suis-je ?","answer":"L'Agent KSK Allemand","npc":"L'Agent KSK Allemand"},{"id":41,"question":"Je connais les rituels que vous ignorez. Qui suis-je ?","answer":"L'Agent SAS Britannique","npc":"L'Agent SAS Britannique"},{"id":42,"question":"Je poursuis un homme qui n'existe pas encore. Qui suis-je ?","answer":"L'Agent SEAL Américain","npc":"L'Agent SEAL Américain"},{"id":43,"question":"Je détruis ce qui ne peut être détruit. Qui suis-je ?","answer":"L'Agent Delta Force","npc":"L'Agent Delta Force"},{"id":44,"question":"Je trouve les copies dans les archives. Qui suis-je ?","answer":"L'Agent KAPO Norvégien","npc":"L'Agent KAPO Norvégien"},{"id":45,"question":"Je vole ce qui est sacré. Qui suis-je ?","answer":"L'Agent Mossad Noir","npc":"L'Agent Mossad Noir"},{"id":46,"question":"Je veux ce qui tue sans bruit. Qui suis-je ?","answer":"L'Agent GRU Russe","npc":"L'Agent GRU Russe"},{"id":47,"question":"Je surveille les milliards invisibles. Qui suis-je ?","answer":"L'Agent BND Allemand","npc":"L'Agent BND Allemand"},{"id":48,"question":"Je manipule ce que vous ressentez sans vous toucher. Qui suis-je ?","answer":"L'Agent ASIO Australien","npc":"L'Agent ASIO Australien"},{"id":49,"question":"Je suis la trace d'un sabotage que personne n'a revendiqué. Qui suis-je ?","answer":"L'Agent CNI Espagnol","npc":"L'Agent CNI Espagnol"},{"id":50,"question":"Je garde les secrets que même les morts ne doivent pas connaître. Qui suis-je ?","answer":"L'Agent SIS Suisse","npc":"L'Agent SIS Suisse"},{"id":51,"question":"Je parle avec votre voix. Qui suis-je ?","answer":"L'Agent NIS Coréen","npc":"L'Agent NIS Coréen"},{"id":52,"question":"Je connais les routes que personne ne voit. Qui suis-je ?","answer":"L'Agent RAW Indien","npc":"L'Agent RAW Indien"},{"id":53,"question":"Je surveille ceux qui gouvernent sans jamais gouverner. Qui suis-je ?","answer":"L'Agent DGSI Français","npc":"L'Agent DGSI Français"},{"id":54,"question":"Je cherche les copies humaines. Qui suis-je ?","answer":"L'Agent MI7 Britannique","npc":"L'Agent MI7 Britannique"},{"id":55,"question":"Je connais le rituel caché dans les pages perdues. Qui suis-je ?","answer":"L'Agent Secret Vatican","npc":"L'Agent Secret Vatican"}],"npcs":[{"id":1,"name":"Milliardaire Mort","category":"Pouvoir & IA"},{"id":2,"name":"IA Hydra Centrale","category":"Pouvoir & IA"},{"id":3,"name":"Dictateur Fils","category":"Pouvoir & IA"},{"id":4,"name":"Président Corrompu","category":"Pouvoir & IA"},{"id":5,"name":"Ministre Sécurité","category":"Pouvoir & IA"},{"id":6,"name":"Ministre Justice","category":"Pouvoir & IA"},{"id":7,"name":"Sénateur Hydra","category":"Pouvoir & IA"},{"id":8,"name":"Scientifique Alpha","category":"Scientifiques & Secte"},{"id":9,"name":"Scientifique Omega","category":"Scientifiques & Secte"},{"id":10,"name":"Chef Secte Hydra","category":"Scientifiques & Secte"},{"id":11,"name":"Grand Prêtre Hydra","category":"Scientifiques & Secte"},{"id":12,"name":"Maître Paradis Fiscaux","category":"Scientifiques & Secte"},{"id":13,"name":"Chanteur Chantage","category":"Scientifiques & Secte"},{"id":14,"name":"Architecte Coup Monté","category":"Scientifiques & Secte"},{"id":15,"name":"CIA","category":"Espions internationaux"},{"id":16,"name":"MI6","category":"Espions internationaux"},{"id":17,"name":"DGSE","category":"Espions internationaux"},{"id":18,"name":"Mossad","category":"Espions internationaux"},{"id":19,"name":"Clone Hydra","category":"Espions internationaux"},{"id":20,"name":"Hacker Fantôme","category":"Espions internationaux"},{"id":21,"name":"GIGN","category":"Espions internationaux"},{"id":22,"name":"KGB","category":"Espions internationaux"},{"id":23,"name":"FSB","category":"Espions internationaux"},{"id":24,"name":"NSA","category":"Espions internationaux"},{"id":25,"name":"Interpol","category":"Espions internationaux"},{"id":26,"name":"Suisse","category":"Espions internationaux"},{"id":27,"name":"Canada","category":"Espions internationaux"},{"id":28,"name":"Japon","category":"Espions internationaux"},{"id":29,"name":"Allemagne","category":"Espions internationaux"},{"id":30,"name":"Italie","category":"Espions internationaux"},{"id":31,"name":"Espagne","category":"Espions internationaux"},{"id":32,"name":"Australie","category":"Espions internationaux"},{"id":33,"name":"Brésil","category":"Espions internationaux"},{"id":34,"name":"Afrique du Sud","category":"Espions internationaux"},{"id":35,"name":"Corée","category":"Espions internationaux"},{"id":36,"name":"Enquêteur Principal Hydra","category":"Enquêteurs & Forces spéciales"},{"id":37,"name":"Enquêtrice Internationale","category":"Enquêteurs & Forces spéciales"},{"id":38,"name":"GIPN","category":"Enquêteurs & Forces spéciales"},{"id":39,"name":"RAID","category":"Enquêteurs & Forces spéciales"},{"id":40,"name":"KSK Allemand","category":"Enquêteurs & Forces spéciales"},{"id":41,"name":"SAS Britannique","category":"Enquêteurs & Forces spéciales"},{"id":42,"name":"SEAL Américain","category":"Enquêteurs & Forces spéciales"},{"id":43,"name":"Delta Force","category":"Enquêteurs & Forces spéciales"},{"id":44,"name":"KAPO Norvégien","category":"Enquêteurs & Forces spéciales"},{"id":45,"name":"Mossad Noir","category":"Enquêteurs & Forces spéciales"},{"id":46,"name":"GRU Russe","category":"Enquêteurs & Forces spéciales"},{"id":47,"name":"BND Allemand","category":"Enquêteurs & Forces spéciales"},{"id":48,"name":"ASIO Australien","category":"Enquêteurs & Forces spéciales"},{"id":49,"name":"CNI Espagnol","category":"Enquêteurs & Forces spéciales"},{"id":50,"name":"SIS Suisse","category":"Enquêteurs & Forces spéciales"},{"id":51,"name":"NIS Coréen","category":"Enquêteurs & Forces spéciales"},{"id":52,"name":"RAW Indien","category":"Enquêteurs & Forces spéciales"},{"id":53,"name":"DGSI Français","category":"Enquêteurs & Forces spéciales"},{"id":54,"name":"MI7 Britannique","category":"Enquêteurs & Forces spéciales"},{"id":55,"name":"Agent Secret Vatican","category":"Enquêteurs & Forces spéciales"}],"end_documents":[{"id":1,"title":"Rapport Final Hydra","text":"Le protocole Hydra-Core a été déclenché avant l'incident. La victime n'était pas le milliardaire, mais son clone. Les poisons Alpha et Omega ont été utilisés pour tester la loyauté des membres Hydra. L'IA Hydra a volontairement effacé les preuves pour protéger le véritable dirigeant. Le projet Hydra continue."},{"id":2,"title":"Message du Milliardaire","text":"Vous avez cru enquêter sur ma mort. Mais je suis vivant. Ce que vous avez découvert n'est qu'une partie du programme. Hydra ne meurt jamais. Vous êtes désormais tous liés au protocole."},{"id":3,"title":"Décryptage IA","text":"Il n'est pas celui que vous croyez. Le clone a été éliminé pour masquer la vérité. Hydra a infiltré chaque zone. Le Chef Hydra est déjà remplacé."},{"id":4,"title":"Ordre Ultime Hydra","text":"Tous les fragments IA doivent être réunis. Le Livre Ancien doit être restauré. Le poison Omega doit être neutralisé. Le projet Hydra doit être relancé sous un nouveau nom."},{"id":5,"title":"Mémoire du Clone","text":"Je n'étais qu'une copie. Mais j'ai compris trop tard. Hydra m'a créé pour tester la fidélité de ses membres. Je meurs pour que le vrai survive."},{"id":6,"title":"Note du Chef Hydra","text":"Le jeu est terminé. Mais Hydra ne s'arrête jamais. Chaque joueur a accompli son rôle. Le protocole redémarre dans 72 heures."},{"id":7,"title":"Synthèse des zones","text":"Zone 1 : neutre. Zone 2 : traces Alpha. Zone 3 : traces Omega. Zone 4 : sabotage confirmé. Zone 5 : bijou manquant. Zone 6 : activité biologique. Zone 7 : livre falsifié. Zone 8 : IA corrompue."},{"id":8,"title":"Conclusion du Maître du Jeu","text":"Le milliardaire est vivant. Le clone est mort. Hydra a manipulé tout le monde. Les poisons ont révélé la loyauté des joueurs. Le protocole Hydra redémarre. Fin du cycle."}],"gm_guide":[{"phase":1,"title":"Accueil et présentation","duration":"15 min","text":"Accueille les joueurs, distribue les enveloppes si ce n'est pas déjà fait. Explique les règles : enquête libre, chacun peut interroger n'importe qui, les indices sont dans les zones. Révèle la mort du milliardaire."},{"phase":2,"title":"Enquête libre","duration":"1h30 à 2h","text":"Les joueurs explorent les 8 zones. Ils peuvent interroger les PNJ. Ils échangent leurs fragments IA ou les cachent. Milo (Mario ou Andrea) trouve des indices physiques."},{"phase":3,"title":"Révélations","duration":"30 min","text":"Les fragments IA sont rassemblés. Le livre ancien est restauré. La vérité émerge : le milliardaire est vivant, la victime est un clone."},{"phase":4,"title":"Accusation finale","duration":"15 min","text":"Les joueurs votent pour désigner le coupable, le saboteur, le clone, celui qui a été hypnotisé. Révèle les documents de fin."},{"phase":5,"title":"Fin","duration":"15 min","text":"Lecture du rapport final. Annonce du gagnant. Remerciements et apéritif."}],"print_checklist":["19 fiches personnages (Ethan, Serge, Silvie, Fabrice, Pineau, Meal, Cécile, Annie, Max, Yoan, Marie-Françoise, Claudie, Andrea, Mario, Tony, Lino, Emy, Milo, Emilie)","19 documents spéciaux (un par joueur)","19 fragments IA (un par joueur)","8 fiches lieux (à afficher dans les zones)","18 objets (à cacher dans les zones)","55 énigmes avec réponses (pour le MJ)","8 documents de fin","Le guide du MJ","Le plan de l'île flottante (à imprimer en grand)"]}$hydra_full$::jsonb,
  true
),
updated_at = now()
where id=1;

notify pgrst,'reload schema';

select
  'HYDRA_FULL_CONTENT_OK' as hydra_full_status,
  jsonb_array_length(settings->'murder_party'->'players') as players_count,
  jsonb_array_length(settings->'murder_party'->'zones') as zones_count,
  jsonb_array_length(settings->'murder_party'->'objects') as objects_count,
  jsonb_array_length(settings->'murder_party'->'enigmas') as enigmas_count,
  jsonb_array_length(settings->'murder_party'->'npcs') as npcs_count,
  jsonb_array_length(settings->'murder_party'->'end_documents') as end_documents_count
from public.birthday_config
where id=1;


-- ============================================================
-- CORRECTION SÉCURITÉ RÉSERVATIONS PRIVÉES
-- Le site utilise les RPC privées pour lire/réserver/déréserver.
-- L'accès direct anon à la table reservations est donc inutile
-- et supprimé pour éviter le contournement du code d'accès.
-- ============================================================

drop policy if exists "Public can view reservations" on public.reservations;
drop policy if exists "Public can create reservations" on public.reservations;
drop policy if exists "Public can cancel reservations" on public.reservations;

revoke select, insert, update, delete on table public.reservations from anon, authenticated;

drop function if exists public.cancel_reservation(text, text);

create or replace function public.get_private_reservations(p_code text)
returns table(
  gift_id text,
  name text,
  created_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $private_reservations$
declare
  v_name text;
begin
  select lac.label
    into v_name
  from public.list_access_codes as lac
  where lac.active=true
    and lac.code=trim(coalesce(p_code,''))
  limit 1;

  if v_name is null then
    raise exception 'Accès refusé.' using errcode='42501';
  end if;

  return query
  select r.gift_id,r.name,r.created_at
  from public.reservations as r
  order by r.created_at desc;
end;
$private_reservations$;

grant execute on function public.get_private_reservations(text) to anon;

create or replace function public.reserve_private_gift(
  p_code text,
  p_gift_id text,
  p_name text
)
returns boolean
language plpgsql
security definer
set search_path = public
as $private_reserve$
declare
  v_name text;
  v_allow boolean;
  v_archived boolean;
begin
  select lac.label
    into v_name
  from public.list_access_codes as lac
  where lac.active=true
    and lac.code=trim(coalesce(p_code,''))
  limit 1;

  if v_name is null then
    raise exception 'Accès refusé.' using errcode='42501';
  end if;

  if lower(trim(coalesce(p_name,''))) <> lower(trim(v_name)) then
    raise exception 'Identité de réservation invalide.' using errcode='42501';
  end if;

  select g.allow_reservation,coalesce(g.archived,false)
    into v_allow,v_archived
  from public.gift_catalog as g
  where g.id=p_gift_id
  limit 1;

  if not found then
    raise exception 'Cadeau introuvable.';
  end if;

  if v_archived then
    raise exception 'Ce cadeau n’est plus disponible.';
  end if;

  if not coalesce(v_allow,true) then
    raise exception 'Les réservations sont désactivées pour ce cadeau.';
  end if;

  begin
    insert into public.reservations(gift_id,name)
    values(p_gift_id,trim(v_name));
  exception
    when unique_violation then
      return false;
  end;

  return true;
end;
$private_reserve$;

grant execute on function public.reserve_private_gift(text,text,text) to anon;

create or replace function public.cancel_private_reservation(
  p_code text,
  p_gift_id text,
  p_name text
)
returns boolean
language plpgsql
security definer
set search_path = public
as $private_cancel$
declare
  v_name text;
  deleted boolean;
begin
  select lac.label
    into v_name
  from public.list_access_codes as lac
  where lac.active=true
    and lac.code=trim(coalesce(p_code,''))
  limit 1;

  if v_name is null then
    raise exception 'Accès refusé.' using errcode='42501';
  end if;

  if lower(trim(coalesce(p_name,''))) <> lower(trim(v_name)) then
    raise exception 'Identité de réservation invalide.' using errcode='42501';
  end if;

  delete from public.reservations as r
  where r.gift_id=p_gift_id
    and lower(trim(r.name))=lower(trim(v_name))
  returning true into deleted;

  return coalesce(deleted,false);
end;
$private_cancel$;

grant execute on function public.cancel_private_reservation(text,text,text) to anon;

select
  'RESERVATION_SECURITY_OK' as reservation_security_status,
  to_regprocedure('public.get_private_reservations(text)') is not null as private_read_rpc_exists,
  to_regprocedure('public.reserve_private_gift(text,text,text)') is not null as private_reserve_rpc_exists,
  to_regprocedure('public.cancel_private_reservation(text,text,text)') is not null as private_cancel_rpc_exists,
  has_table_privilege('anon','public.reservations','select') as anon_can_select_table,
  has_table_privilege('anon','public.reservations','insert') as anon_can_insert_table,
  has_table_privilege('anon','public.reservations','delete') as anon_can_delete_table;

-- ============================================================
-- TEXTE D'ACCUEIL — CODE D'ACCÈS
-- ============================================================
update public.site_settings
set settings = jsonb_set(
  settings,
  '{access,text}',
  to_jsonb('Bienvenue sur la liste d’Ethan. Entre ton code d’invitation pour afficher les cadeaux, participer aux animations et retrouver les informations de la journée. Le plus simple est d’utiliser directement le lien qui t’a été envoyé : il peut ouvrir automatiquement la bonne page.'::text),
  true
),
updated_at = now()
where id=1;


-- ============================================================
-- HARDENING LOT A : SUGGESTIONS ET CAGNOTTES
-- ============================================================

drop policy if exists "Public can view approved gift suggestions" on public.gift_suggestions;
drop policy if exists "Public can create gift suggestions" on public.gift_suggestions;
revoke select, insert, update, delete on table public.gift_suggestions from anon, authenticated;
revoke usage, select on sequence public.gift_suggestions_id_seq from anon, authenticated;

create or replace function public.get_private_gift_suggestions(p_code text)
returns table(id bigint,name text,gift_name text,link text,message text,created_at timestamptz)
language plpgsql security definer set search_path=public
as $$
begin
  if not exists(select 1 from public.list_access_codes where active=true and code=trim(coalesce(p_code,''))) then
    raise exception 'Accès refusé.' using errcode='42501';
  end if;
  return query
  select s.id,s.name,s.gift_name,s.link,s.message,s.created_at
  from public.gift_suggestions s
  where s.status='approved'
  order by s.created_at desc
  limit 100;
end;
$$;

grant execute on function public.get_private_gift_suggestions(text) to anon;

create or replace function public.submit_private_gift_suggestion(
  p_code text,p_gift_name text,p_link text default null,p_message text default null
)
returns bigint
language plpgsql security definer set search_path=public
as $$
declare v_name text; v_id bigint;
begin
  select lac.label into v_name from public.list_access_codes lac
  where lac.active=true and lac.code=trim(coalesce(p_code,'')) limit 1;
  if v_name is null then raise exception 'Accès refusé.' using errcode='42501'; end if;
  if char_length(trim(coalesce(p_gift_name,''))) not between 1 and 120 then raise exception 'Nom de cadeau invalide.'; end if;
  if p_link is not null and char_length(trim(p_link))>1000 then raise exception 'Lien invalide.'; end if;
  if p_message is not null and char_length(trim(p_message))>500 then raise exception 'Message invalide.'; end if;
  insert into public.gift_suggestions(name,gift_name,link,message,status)
  values(trim(v_name),trim(p_gift_name),nullif(trim(coalesce(p_link,'')),''),nullif(trim(coalesce(p_message,'')),''),'pending')
  returning id into v_id;
  return v_id;
end;
$$;

grant execute on function public.submit_private_gift_suggestion(text,text,text,text) to anon;

create or replace function public.delete_private_gift_suggestion(p_code text,p_id bigint)
returns boolean
language plpgsql security definer set search_path=public
as $$
declare v_name text;
begin
  select lac.label into v_name from public.list_access_codes lac
  where lac.active=true and lac.code=trim(coalesce(p_code,'')) limit 1;
  if v_name is null then raise exception 'Accès refusé.' using errcode='42501'; end if;
  delete from public.gift_suggestions
  where id=p_id and lower(trim(name))=lower(trim(v_name));
  return found;
end;
$$;

grant execute on function public.delete_private_gift_suggestion(text,bigint) to anon;

drop policy if exists "Public can view approved fundraisers" on public.fundraisers;
drop policy if exists "Public can create fundraisers" on public.fundraisers;
revoke select, insert, update, delete on table public.fundraisers from anon, authenticated;
revoke usage, select on sequence public.fundraisers_id_seq from anon, authenticated;

create or replace function public.get_private_fundraisers(p_code text)
returns table(id bigint,title text,description text,goal_amount numeric,status text,created_at timestamptz)
language plpgsql security definer set search_path=public
as $$
begin
  if not exists(select 1 from public.list_access_codes where active=true and code=trim(coalesce(p_code,''))) then
    raise exception 'Accès refusé.' using errcode='42501';
  end if;
  return query
  select f.id,f.title,f.description,f.goal_amount,f.status,f.created_at
  from public.fundraisers f where f.status='approved'
  order by f.created_at desc;
end;
$$;

grant execute on function public.get_private_fundraisers(text) to anon;

create or replace function public.submit_private_fundraiser(
  p_code text,p_title text,p_description text,p_goal_amount numeric
)
returns bigint
language plpgsql security definer set search_path=public
as $$
declare v_id bigint;
begin
  if not exists(select 1 from public.list_access_codes where active=true and code=trim(coalesce(p_code,''))) then
    raise exception 'Accès refusé.' using errcode='42501';
  end if;
  if char_length(trim(coalesce(p_title,''))) not between 1 and 120 then raise exception 'Nom de cagnotte invalide.'; end if;
  if p_description is not null and char_length(trim(p_description))>500 then raise exception 'Description invalide.'; end if;
  if p_goal_amount is null or p_goal_amount<=0 or p_goal_amount>50000 then raise exception 'Objectif invalide.'; end if;
  insert into public.fundraisers(title,description,goal_amount,status)
  values(trim(p_title),nullif(trim(coalesce(p_description,'')),''),round(p_goal_amount,2),'pending')
  returning id into v_id;
  return v_id;
end;
$$;

grant execute on function public.submit_private_fundraiser(text,text,text,numeric) to anon;

select
  'PRIVATE_LOT_A_OK' as security_status,
